import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/10-How-does-a-computer-analyze-a-problem.html","title":"10- 从“开关”到“计算”：计算机的另一种思维方式","lang":"zh-CN","frontmatter":{"title":"10- 从“开关”到“计算”：计算机的另一种思维方式","icon":"read","date":"2025-04-14T20:06:16.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":17,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"b44db4c520933876a80fb48fe6f09ac7a07cceb7","time":1744696920000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"b39575629342f238e70a02209a2a45f0151befb6","time":1744638767000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"81ce8b2f8f5643f8b22bf050ce4e1882c493191c","time":1744636535000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"添加旗语"},{"hash":"656e52012f42868e491db278c5e566ebf11e5938","time":1744635479000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"非运算"},{"hash":"13b8f67b21d91b50c2cd02a56ea5312a734f7e3a","time":1744635381000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新"},{"hash":"13787b2fe4f7a92434e2ac378bc9d148ae3f69ab","time":1744632686000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成10-计算机怎么分析问题？"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":7.39,"words":2216},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/10-How-does-a-computer-analyze-a-problem.md"}`),a={name:`10-How-does-a-computer-analyze-a-problem.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>在前面，提到了计算机只使用两种数字——0 和 1。虽然这种“二进制”跟我们日常使用的十进制不同，但它已经足够让计算机开始运算了。</p><p>可你有没有想过，光有数字是不够的。想象一下，小学刚学完1到9之后，是不是紧接着就要学加减乘除？同理，计算机在掌握了0和1之后，也必须掌握一套适合自己的“运算规则”。</p><p>你可能会问：“运算规则不就是加减乘除吗？这还有什么花样？”其实，计算机用的并不是我们平时的那一套。它有一套<strong>专属的运算体系</strong>，这套体系更适合它的“电子大脑”来理解和执行。</p><p>虽然传统的四则运算看似简单，但在电子电路中直接运用其实并不合适。试想一下，用不同电压来代表各个数字，既复杂又容易受外界干扰。事实证明，电路中的电流状态只有两种：开和关，这样的特性决定了我们必须采用与众不同的运算方式。这时，逻辑运算应运而生，它完全利用“开”和“关”来完成各种操作。</p><p>所以，你应该猜到了。这一套规则，叫做<strong>逻辑运算（Logical Operation）</strong>，也叫做布尔运算。我们本书后面的 Python 部分也会讲解到布尔型，里面也有逻辑运算符。</p><h2 id="_1-一组灯泡就能理解的-逻辑思维" tabindex="-1"><a class="header-anchor" href="#_1-一组灯泡就能理解的-逻辑思维"><span>1. 一组灯泡就能理解的“逻辑思维”</span></a></h2><p>我们来玩个小游戏，换一个身份——假设你现在是计算机中的一个电子元件。计算机内部的一切，最终都归结为两个状态：“通电”或“断电”。我们用灯泡来代表这两种状态：<strong>亮</strong>表示有电，<strong>灭</strong>表示没电。</p><h3 id="_1-1-非-运算-not" tabindex="-1"><a class="header-anchor" href="#_1-1-非-运算-not"><span>1.1 “非”运算（NOT）</span></a></h3><figure><img src="/assets/raw-20250414210337773-CE5jScaU.png" alt="非运算" tabindex="0" loading="lazy"><figcaption>非运算</figcaption></figure><p>你看到旁边小伙伴的灯泡亮着，你就把你的灯关掉；他灯泡灭了，你就打开你的灯。总之，就是<strong>跟他反着来</strong>。这就是“非”运算——这样做就好比对输入信号做了“反转”，不论是什么，就返回它的反面。</p><h3 id="_1-2-或-运算-or" tabindex="-1"><a class="header-anchor" href="#_1-2-或-运算-or"><span>1.2 “或”运算（OR）</span></a></h3><figure><img src="/assets/or-Co2DH75T.png" alt="或运算" tabindex="0" loading="lazy"><figcaption>或运算</figcaption></figure><p>现在，对方有两个灯泡。只要<strong>其中有一个是亮的</strong>，你就把你的灯也点亮；如果他那两个都灭了，那你就不点灯。这叫“或”运算，只要有一个满足，就点亮。</p><h2 id="_1-3-与-运算-and" tabindex="-1"><a class="header-anchor" href="#_1-3-与-运算-and"><span>1.3 “与”运算（AND）</span></a></h2><figure><img src="/assets/raw-20250414205351559-DmEV1zKV.png" alt="与运算" tabindex="0" loading="lazy"><figcaption>与运算</figcaption></figure><p>还是两个灯泡。这次你得严格一点：<strong>只有当对方两个灯泡都亮着</strong>，你才点亮自己的灯；否则，灯就保持关闭。这就是“与”运算，讲究“全部都满足”。</p><figure><img src="/assets/%E4%B9%94%E6%B2%BB%E5%B8%83%E5%B0%94-U5JgwUC8.png" alt="乔治·布尔" tabindex="0" loading="lazy"><figcaption>乔治·布尔</figcaption></figure><p>这三种操作构成了逻辑运算最基础的部分，而完整的逻辑体系正是由数学家乔治·布尔提出，因此这种运算方式也被称为 <strong>“布尔运算（Boolean Logic）“</strong> 。布尔最初提出这套理论时，虽然在当时并没有受到广泛关注，但它后来成为电子计算的基石。</p><p>其实，计算机的很多最基础的计算，都是基于这三种逻辑规则来完成的。</p><h2 id="_2-布尔的-逻辑革命" tabindex="-1"><a class="header-anchor" href="#_2-布尔的-逻辑革命"><span>2. 布尔的“逻辑革命”</span></a></h2><figure><img src="/assets/raw-20250414213241870-B9YAmxbg.png" alt="克劳德·香农" tabindex="0" loading="lazy"><figcaption>克劳德·香农</figcaption></figure><p>那么，为什么现代计算机会舍弃传统的加减乘除，而选择这种看似简单却极为高效的逻辑运算呢？</p><p>因为，乔治·布尔生活在19世纪，他的逻辑体系起初并没有被广泛应用。但在多年后，一位充满好奇心的科学家重新点燃了这套理论的火花，这人就是——<strong>克劳德·香农</strong>。</p><p>香农是一位集天赋与幽默于一身的天才。别看他外表严肃，他发明的东西一个比一个有趣：电动跳跳鞋、自动迷宫老鼠、自己会把自己关上的“无用机器盒子”……可别小看这些玩意儿，背后都是科学思维在闪光。</p><p>真正让香农被奉为“信息时代奠基人”的，是他在研究电路时提出的一个划时代的想法：<strong>如果电路的通断可以用 0 和 1 表示，那是不是可以用布尔运算来控制这些电路的行为？</strong></p><p>这个念头不只是天马行空。他立刻动手设计了模型，证明了<strong>布尔逻辑可以直接用于控制电路的开关，从而执行各种计算任务</strong>。</p><h2 id="_3-为什么不是加减乘除" tabindex="-1"><a class="header-anchor" href="#_3-为什么不是加减乘除"><span>3. 为什么不是加减乘除？</span></a></h2><p>你可能会疑惑，既然加法那么常见，为什么不直接在电路里实现加减法呢？</p><p>回顾早期的实验：若用电压高低来表示数字：1 伏表示数字 1，2 伏表示 2……但一台计算机每秒要处理成千上万种数据，如果每种数字都靠电压来表示，那就需要成百上千种精确的电压，稍有干扰就可能出错。并且计算机在执行复杂运算时或旁边有其他机器的干扰，电压也很容易出现偏差，计算就会出错。所以，加减乘除法用在计算机电路里不太合适。</p><p>当时人们还尝试过：建立三进制计算机，结果不仅电路复杂，还极易出错。</p><p>逻辑运算就不一样了。它只需要区分“有电”与“无电”，对应的正好就是 1 和 0。就像我们之前提到的小灯泡，要么亮，要么灭，没有中间状态，这让计算机的电路既稳定又高效。</p><p>所以，布尔运算 + 二进制，简直就是为计算机量身定做的“黄金搭档”。</p><p>而在我们日常编程中，虽然看不到底层电路中灯的闪烁，但正是这种“开和关”构成的基本逻辑，使得计算机能够高效地将复杂问题转化为简单的信号处理任务，从而实现各种功能。简单的二进制和逻辑运算背后，正隐藏着一种强大的<strong>问题抽象</strong>和<strong>转化思维</strong>，这是所有编程思想的重要组成部分。</p><h2 id="_4-香农的贡献-将理论化为现实" tabindex="-1"><a class="header-anchor" href="#_4-香农的贡献-将理论化为现实"><span>4. 香农的贡献：将理论化为现实</span></a></h2><p>香农在读硕士的时候，看到了布尔提出的布尔运算。他觉得，这套规则用到电路里简直是太合适了。</p><p>你想，咱们前面说布尔运算的时候，是拿小灯泡的亮和灭打比方的，其实，小灯泡的亮和灭不就是计算机电路里面的有电和没电吗？</p><figure><img src="/assets/c20e92a466d85ab085ba6709a9f6c4cb-BNpHoLCw.png" alt="基础电路" tabindex="0" loading="lazy"><figcaption>基础电路</figcaption></figure><p>所以，布尔运算的规则再加上二进制，正好就可以让计算机处理信息。当然了，香农也在二进制和布尔运算的基础上构建了一套更复杂的体系，好让计算机能够进行各种各样的运算。</p><p>需要注意的是：在香农生活的年代，还没有真正意义上的电子计算机。</p><p>他提出的，是一套可以把逻辑运算用在电路上的方法。而这一思想，直接成为了现代计算机的基础框架。</p><p>之后，计算机的硬件设计、电路逻辑、信号处理、乃至我们今天用的手机、电脑，都是建立在香农这套理论之上的。</p><p>今天我们使用的数字通信方式（包括你正在听的音频、打的电话、上的网）也都离不开香农的那套体系。他所提出的“用二进制+逻辑运算处理电信号”的方法，成为信息时代的核心支柱。</p><h2 id="_5-回到编程思维" tabindex="-1"><a class="header-anchor" href="#_5-回到编程思维"><span>5. 回到编程思维</span></a></h2><p>你可能会问：这些不是底层硬件的事吗？跟编程有什么关系？</p><p>那我们就得重新提一下“<strong>问题转化</strong>”这件事。</p><p>计算机只识别电流的“开”与“关”。编程的本质，就是要<strong>把我们的问题转化成一系列“开或关”的指令组合</strong>，也就是一串 0 和 1，然后用逻辑运算规则去一步步处理它们，最终得到结果。</p><p>换句话说，<strong>逻辑运算不仅是计算机运行的基础，也是编程思维的一种核心体现</strong>。它教会我们如何把复杂的问题，拆解为最基础的判断与操作。</p>`,47)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};